                            record._modelOffset.Z = cursor.NextF32();
                        }
                        break;

                    case 22:
                        TcbTable.CheckColumn(column, "Monster.Tags", TcbTable.KindArray, false, TcbTable.ElementString);
                        cursor = new TcbColumnCursor(reader, column, count, "Monster.Tags");
                        for (int i = 0; i < count; i++)
                        {
                            var record = records[i];
                            int elementCount;
                            elementCount = cursor.NextLength();
                            record._tags = new string[elementCount];
                            for (int j = 0; j < elementCount; ++j)
                            {
                                record._tags[j] = cursor.NextString();
                            }
                        }
                        break;

                    default:
                        // A column added after this code was generated. Its block length
                        // says how far to move on.
                        reader.Skip(column.ByteLength);
                        break;
                }

                TcbTable.CheckBlockEnd(reader, column, blockEnd);
            }

            // Index mapping. Sized to the rows, so nothing rehashes on the way in, and a
            // duplicate key throws here - before any of this is visible.
            var recordsByMonsterId = new Dictionary<string, Record>(count);
            foreach (var record in records)
                recordsByMonsterId.Add(record.MonsterId, record);
            var recordsByDisplayCode = new Dictionary<string, Record>(count);
            foreach (var record in records)
                recordsByDisplayCode.Add(record.DisplayCode, record);

            // Published. Everything above succeeded, and the barrier is what keeps the writes
            // that built these from being seen after the references to them - a reader on
            // another thread gets the whole table or the previous one, never half of either.
            System.Threading.Thread.MemoryBarrier();

            _records = records;
            _recordsByMonsterId = recordsByMonsterId;
            _recordsByDisplayCode = recordsByDisplayCode;

            return Task.CompletedTask;
        }

        public override string ToString()
        {
            var sb = new StringBuilder();
            ToStringHelper.ToString(_records, sb);
            return sb.ToString();
        }
    }
} // namespace Wildling.Data
